#!/usr/bin/env python3
"""Source-backed physical runtime/control contract; no fitted latency defaults."""
import argparse,hashlib,json,re
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def cite(path,text):
 p=R/path;lines=p.read_text().splitlines();found=[n+1 for n,line in enumerate(lines)if text in line]
 if not found:raise ValueError('Missing source citation '+str(p)+' '+text)
 return {'path':str(p),'sha256':sha(p),'lines':found,'literal':text}
def main():
 p=argparse.ArgumentParser(__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);source=R/'build/saturn-timing-source-v1';profiles={}
 for k in ['compute','rocket']:
  j=json.loads((source/k/'ports.json').read_text());rtl=source/k/'rtl';backend=(rtl/(j['backend_module']+'.sv')).read_text();q={}
  for module,name in re.findall(r'^  (\w+) (vdq|vlissq|vsissq|vpissq|vxissq_\w+) \(',backend,re.M):
   text=(rtl/(module+'.sv')).read_text();depth=len(set(re.findall(r'output\s+io_(?:peek|hazards)_(\d+)_valid',text)));q[name]={'module':module,'entries':depth,'sha256':sha(rtl/(module+'.sv'))}
  rfmodule='RegisterFile'if k=='compute'else'RegisterFile_2';rf=rtl/(rfmodule+'.sv');banks=re.findall(r'^  RegisterFileBank\w* (vrf_\d+) \(',rf.read_text(),re.M);vat=re.search(r'input\s+\[(\d+):0\]\s+io_vat_tail',backend);width=int(vat[1])+1
  profiles[k]={'top_module':j['top_module'],'source_harts':j['source_harts'],'VLEN_bits':j['VLEN_bits'],'DLEN_bits':j['DLEN_bits'],'ELEN_bits':64,'OPU':j['OPU'],'VRF_banks':len(banks),'VRF_EGs':8192//j['DLEN_bits'],'physical_VRF_bits':8192,'VAT_slots':1<<width,'queues':q,'TL_bus_bytes':4*8 if k=='compute'else 8,'clock_IDs':j['clock_IDs'],'physical_source_sha256':j['source_files'],'source_port_schema_sha256':sha(source/k/'ports.json')}
 facts=[
 ('source scalar stages','EX candidate/ready and real EXfire are separate. PFC S1 records candidate; S1 kill includes source MEMkill and the saved EXfire; S2 is another source edge. Retirement, replay and late completion are distinct from backend completion.',[cite('third_party/saturn/src/main/scala/shuttle/Frontend.scala','pfc.io.s1.kill := io.core.mem.kill'),cite('third_party/saturn/src/main/scala/frontend/PipelinedFaultCheck.scala','s1_valid := io.s0.in.fire'),cite('third_party/saturn/src/main/scala/frontend/PipelinedFaultCheck.scala','s2_valid := s1_valid && !io.s1.kill')]),
 ('runtime queues and VAT','Dispatcher VAT availability, issue and memory handshakes are computed internally; all configured VDQ/issue queues, sequencers, scoreboards and VMU queues remain source state. The projection ledger never supplies state or readiness.',[cite('third_party/saturn/src/main/scala/frontend/Dispatch.scala','io.issue.ready := vat_available'),cite('third_party/saturn/src/main/scala/frontend/Dispatch.scala','when (io.dis.fire)'),cite('third_party/saturn/src/main/scala/backend/Backend.scala','val vdq = Module')]),
 ('chaining and hazards','EG intents combine older queued/sequence hazards, same/other FU pipe writes, iterative writes and OPU readout scoreboard. Operand readiness and age are resolved at actual read ports; no blanket instruction latency is used.',[cite('third_party/saturn/src/main/scala/backend/Backend.scala','seq.io.older_writes := older_pipe_writes'),cite('third_party/saturn/src/main/scala/backend/Backend.scala','val older_wintents ='),cite('third_party/saturn/src/main/scala/backend/Backend.scala','val older_same_pipe_writes')]),
 ('VRF ports and reservation','Source3R1W banks arbitrate by age/round-robin, reserve future write slots and use a one-entry LL hiccup buffer per bank. Regular writes have priority; actual masks update bits. Bank count is taken from elaborated RegisterFile instances, not default Scala parameters.',[cite('third_party/saturn/src/main/scala/backend/RegisterAccess.scala','// 3R1W banks'),cite('third_party/saturn/src/main/scala/backend/RegisterFile.scala','when (!io.write.valid)'),cite('third_party/saturn/src/main/scala/backend/RegisterFile.scala','scheduler.io.reqs(j).request'),cite('third_party/saturn/src/main/scala/backend/RegisterFile.scala','class OldestRRArbiter')]),
 ('VRF reset sweep','Real RegisterAccess LLwriter0 emits0/fullDLEN at reset_ctr and advances64/32 core edges after reset; normal sequencer read-ready is held low. Constructor data is not initialized. Early reads are source-held; early compute load writes can precede a later scrub of another bank and be erased. A universal instant first-access-zero abstraction is not proved.',[cite('third_party/saturn/src/main/scala/backend/RegisterAccess.scala','val resetting = RegInit(true.B)'),cite('third_party/saturn/src/main/scala/backend/RegisterAccess.scala','vrf.io.ll_writes(0).bits.data := 0.U'),cite('third_party/saturn/src/main/scala/backend/RegisterAccess.scala','reset_ctr := reset_ctr + 1.U'),cite('third_party/saturn/src/main/scala/backend/RegisterAccess.scala','io.vxs.foreach(_.rvs2.req.ready := false.B)')]),
 ('VMV dummy source reads','The move alias shares MERGE decode. MERGE AlwaysReadsVM and ordinary VS2 read intent remain hardware timing dependencies even where architectural move data ignores old VRF; those source requests are not optimized away.',[cite('third_party/saturn/src/main/scala/insns/Instructions.scala','object MERGE'),cite('third_party/saturn/src/main/scala/backend/ExecuteSequencer.scala','io.rvs2.valid := valid && renv2'),cite('third_party/saturn/src/main/scala/backend/ExecuteSequencer.scala','!(renvm && !io.rvm.ready)')]),
 ('OPU control and array boundary','Exact frozen OPU controller, backend control register, array and readout RegEnable are contained in compute cut. io_busy alone is not quiescence: OPU FP8/readout tails and some issue state are not represented by that single output.',[cite('third_party/saturn/src/main/scala/backend/Backend.scala','vopu_ctrl_reg := vos.get.io.iss.bits'),cite('third_party/saturn/src/main/scala/backend/Backend.scala','bits.data := RegEnable('),cite('third_party/saturn/src/main/scala/backend/Backend.scala','io.busy := vdq.io.deq.valid')]),
 ('Rocket route','Reset-constant load_use_tl/store_use_tl select ATL. Hella256 remains a physical external interface but its vector request-valid inputs are specialized inactive in saved source. No dormant Hella-path coverage is claimed.',[cite('third_party/saturn/src/main/scala/rocket/Integration.scala','val load_use_tl_reg = RegInit(true.B)'),cite('third_party/saturn/src/main/scala/rocket/Integration.scala','val store_use_tl_reg = RegInit(true.B)'),cite('hardware/memory-paths.json','load_use_tl')]),
 ('external scalar/vector FPU','Rocket SharedFP service has actual65-bit recoded operand/result ports. Real364 request/response events under scalar FADD contention were captured; no fixed service delay is invented. Shared scalar-core FPU fflags handling is external to this unit boundary, not inferred from unit-local set_fflags alone.',[cite('third_party/saturn/src/main/scala/rocket/Integration.scala','io.fp_req <> vu.io.fp_req'),cite('third_party/saturn/src/main/scala/rocket/Integration.scala','vu.io.fp_resp.bits := io.fp_resp.bits'),cite('third_party/saturn/src/main/scala/backend/Backend.scala','io.set_fflags.valid := vxus.flatten')]),
 ('actual TL beat events','ATL requests/responses preserve source IDs, opcode,size,byte masks and each actual beat. Compute ATL256 and Rocket ATL64 are distinct from DLEN128/256. Width/arbitration/CDC outside each unit must be connected through exact physical adaptors.',[cite('third_party/saturn/src/main/scala/shuttle/Integration.scala','atlNode := TLBuffer'),cite('third_party/saturn/src/main/scala/rocket/Integration.scala','atlNode := TLBuffer'),cite('hardware/memory-paths.json','vector')]),
 ('scope and knownness','SDK constructor requires explicit two-state-reference scope. All physical words/widths/hart IDs are checked. Reset/unknown inactive payload is not a numeric certification; qualification masks follow source valid/protocol semantics. Tile MRF has no global reset zero; explicit VTZERO is used for known VME accumulator values.',[cite('timing/saturn_timing.hpp','enum class ReferenceScope'),cite('timing/saturn_timing.hpp','No implicit reset'),cite('hardware/evidence/outer-product-unit.scala','val regs = Reg(')])]
 report={'schema':'iris.saturn_runtime_source_contract.v1','profiles':profiles,'facts':[{'name':n,'value':v,'source':s}for n,v,s in facts],'reference_source_fir_sha256':'f1b36c8565bd67825c636af40079ea048a9196bf1e36fcb719270411270201f4','source_context_repositories':json.loads((R/'hardware/manifest.json').read_text())['repositories'],'parameter_fitting_performed':False,'whole_SoC_or_Ethan_image_association':False,'hardware_contacted':False};(out/'source-contract.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'profiles':{k:{n:v for n,v in j.items()if n in['VRF_banks','VRF_EGs','VAT_slots','queues']}for k,j in profiles.items()},'facts':len(facts),'source_contract_sha256':sha(out/'source-contract.json')}))
if __name__=='__main__':main()
